-- Egg yolks and whites are not separate products: a pantry holds eggs, and a recipe
-- line "Яичный белок" would not match them. Recipes therefore list "Яйцо куриное" in
-- whole eggs even when only a part is used, and nothing told the cook which part.
-- The step that first uses the part now starts with one sentence about it.
--
-- A row is applied only while the recipe keeps its title and the step still starts
-- with the original text, so an edited recipe is not touched and a second run changes nothing.

UPDATE public.recipe_steps AS s
SET instruction = n.note || ' ' || s.instruction
FROM (VALUES
    (13, 'Мусака', 4, 'Растопите масло, вмешайте муку и прогрей', 'От яиц здесь нужны только желтки: отделите их, белки в блюдо не идут.'),  -- только желтки
    (32, 'Курица гунбао', 1, 'Смешайте курицу с яичным белком, ложкой', 'От яйца здесь нужен только белок: отделите его, желток в блюдо не идёт.'),  -- только белок
    (34, 'Крем-брюле', 2, 'Разотрите желтки с сахаром без пены — во', 'От яиц здесь нужны только желтки: отделите их, белки в блюдо не идут.'),  -- только желтки
    (63, 'Паштел де ната', 3, 'Влейте горячий сироп тонкой струйкой в м', 'От яиц здесь нужны только желтки: отделите их, белки в блюдо не идут.'),  -- только желтки
    (192, 'Потица', 2, 'Замесите тесто из муки, опары, желтков,', 'От яиц здесь нужны только желтки: отделите их, белки в блюдо не идут.'),  -- только желтки
    (200, 'Павлова', 1, 'Взбейте белки комнатной температуры до м', 'От яиц здесь нужны только белки: отделите их, желтки в блюдо не идут.'),  -- только белки
    (292, 'Буйабес', 6, 'Взбейте руй: желток, чеснок, шафран, щеп', 'От яйца здесь нужен только желток: отделите его, белок в блюдо не идёт.'),  -- только желток
    (311, 'Пирог с лаймом', 3, 'Взбейте желтки с цедрой двух лаймов до п', 'От яиц здесь нужны только желтки: отделите их, белки в блюдо не идут.'),  -- только желтки
    (343, 'Альфахорес', 2, 'Введите желтки по одному, затем ваниль,', 'От яиц здесь нужны только желтки: отделите их, белки в блюдо не идут.'),  -- только желтки
    (351, 'Шведский яблочный пирог', 7, 'Взбейте желтки с крахмалом, вводите горя', 'От яиц здесь нужны только желтки: отделите их, белки в блюдо не идут.'),  -- только желтки
    (361, 'Гата', 7, 'Нанесите узор вилкой, смажьте желтком и', 'От яйца здесь нужен только желток: отделите его, белок в блюдо не идёт.'),  -- только желток
    (365, 'Лече флан', 3, 'Разотрите желтки венчиком, не взбивая до', 'От яиц здесь нужны только желтки: отделите их, белки в блюдо не идут.'),  -- только желтки
    (378, 'Ватерзой', 6, 'Взбейте желтки со сливками и вводите гор', 'От яиц здесь нужны только желтки: отделите их, белки в блюдо не идут.'),  -- только желтки
    (386, 'Чорба де бурта', 6, 'Взбейте желтки со сливками, вводите горя', 'От яиц здесь нужны только желтки: отделите их, белки в блюдо не идут.'),  -- только желтки
    (407, 'Бакинская пахлава', 1, 'Растворите дрожжи в тёплом молоке, замес', 'От яиц здесь нужны только желтки: отделите их, белки в блюдо не идут.'),  -- только желтки
    (425, 'Тайваньское ананасовое печенье', 5, 'Взбейте масло с сахарной пудрой, желткам', 'От яиц здесь нужны только желтки: отделите их, белки в блюдо не идут.'),  -- только желтки
    (455, 'Бухты', 2, 'Замесите тесто из муки, опары, желтков,', 'От яиц здесь нужны только желтки: отделите их, белки в блюдо не идут.'),  -- только желтки
    (458, 'Бегова чорба', 6, 'Взбейте желтки со сметаной и вводите гор', 'От яиц здесь нужны только желтки: отделите их, белки в блюдо не идут.'),  -- только желтки
    (491, 'Баллокуме', 2, 'Вводите желтки по одному, продолжая взби', 'От яиц здесь нужны только желтки: отделите их, белки в блюдо не идут.')  -- только желтки
) AS n(recipe_id, title, step_no, starts_with, note)
JOIN public.recipes r ON r.id = n.recipe_id AND r.title = n.title AND r.author_id IS NULL
WHERE s.recipe_id = n.recipe_id
  AND s.step_no = n.step_no
  AND starts_with(s.instruction, n.starts_with);
